/* Generated by tools/fw/gen_revh_pins.py from tools/pcb/design_revh.py -- do not edit; run the script again.
 * famicart rev H, U6 (hub): the hub's functions under the names docs/13 gives them ("ピン割り当て", "移植の一覧"),
 * on top of pins_u6.h. GPIO function numbers come from the SDK's hardware/regs/io_bank0.h by name: a pin that
 * does not have the function stops the build. */
#ifndef FAMICART_REVH_PINS_HUB_H
#define FAMICART_REVH_PINS_HUB_H
#include "pins_u6.h"
#include "hardware/platform_defs.h"          /* _u() for the register headers */
#include "hardware/regs/io_bank0.h"

/* microSD (J3) on SPI0: SCK = SD_CLK, TX = SD_CMD, RX = SD_DAT0. The chip select DAT3 / CS (GPIO7) is driven by
 * SIO: SPI0's own CSn only reaches GPIO1 / 5 / 17 / 21 / 33 / 37, and on the hub each of them carries something
 * else (1 SD_CD, 5 SD_DAT1, 17 PLINK_F, 21 SWDIO2, 33 HM2, 37 SWCLK1). 4-bit SD by PIO uses PIN_SD_BASE /
 * PIN_SD_COUNT. Card detect on SD_CD with the pad pull-up (no resistor on the board). */
#define HUB_SD_SPI_INDEX    0
#define HUB_SD_SPI_SCK_PIN  PIN_SD_CLK
#define HUB_SD_SPI_TX_PIN   PIN_SD_CMD
#define HUB_SD_SPI_RX_PIN   PIN_SD_DAT0
#define HUB_SD_SPI_CS_PIN   PIN_SD_DAT3         /* software chip select (SIO), 10k pull-up on the board */
#define HUB_SD_CD_PIN       PIN_SD_CD
#define HUB_SD_SPI_SCK_FUNC IO_BANK0_GPIO2_CTRL_FUNCSEL_VALUE_SPI0_SCLK
#define HUB_SD_SPI_TX_FUNC  IO_BANK0_GPIO3_CTRL_FUNCSEL_VALUE_SPI0_TX
#define HUB_SD_SPI_RX_FUNC  IO_BANK0_GPIO4_CTRL_FUNCSEL_VALUE_SPI0_RX
_Static_assert(HUB_SD_SPI_SCK_PIN == 2, "the function name above is for GPIO2");
_Static_assert(HUB_SD_SPI_TX_PIN == 3, "the function name above is for GPIO3");
_Static_assert(HUB_SD_SPI_RX_PIN == 4, "the function name above is for GPIO4");

/* ADC: on the RP2350B (QFN-80) ADC0-7 are GPIO40-47 (the SDK's ADC_BASE_PIN with PICO_RP2350A 0).
 * volts at the source = volts at the pin x (R_TOP + R_BOTTOM) / R_BOTTOM; R_BOTTOM 0 = a series resistor only. */
#define HUB_ADC_BASE_PIN 40
#define HUB_ADC_V5S_PIN          PIN_V5S
#define HUB_ADC_V5S_CH           (PIN_V5S - HUB_ADC_BASE_PIN)   /* ADC0 */
#define HUB_ADC_V5S_R_TOP        10000  /* R26: +5V - V5S */
#define HUB_ADC_V5S_R_BOTTOM     10000  /* R27: V5S - GND */
#define HUB_ADC_EXT_PIN          PIN_EXT
#define HUB_ADC_EXT_CH           (PIN_EXT - HUB_ADC_BASE_PIN)   /* ADC1 */
#define HUB_ADC_EXT_R_TOP        2200   /* R54: EXT_P - EXT */
#define HUB_ADC_EXT_R_BOTTOM     0      /* none (series resistor only) */
#define HUB_ADC_VBUS_S_PIN       PIN_VBUS_S
#define HUB_ADC_VBUS_S_CH        (PIN_VBUS_S - HUB_ADC_BASE_PIN)   /* ADC2 */
#define HUB_ADC_VBUS_S_R_TOP     10000  /* R44: VBUS - VBUS_S */
#define HUB_ADC_VBUS_S_R_BOTTOM  10000  /* R45: VBUS_S - GND */
/* ADC reference = ADC_AVDD = +3V3: 600 mV x (10000 + 2200) / 2200 (R36 / R37 on the TLV62569's FB),
 * nominal; the resistor and reference tolerances make it 3.21-3.45 V (docs/13 "電源"). */
#define HUB_ADC_VREF_MV 3327
/* USB D+ pull-up only while VBUS_S (VBUS / 2) is above about 1.5 V (docs/13 "起動・書き込み・リセット", 決まり) */
#define HUB_VBUS_S_ON_MV  1500
#define HUB_VBUS_S_OFF_MV 1400

/* PWM: HM2 = the console's M2 through its own 1k (RN18); measuring the duty needs a B (input) channel. PWM2 =
 * the hub's audio output into the RC filter of AUDIO_OUT (RN19). */
#define HUB_HM2_PIN        PIN_HM2
#define HUB_HM2_PWM_SLICE  8
#define HUB_HM2_PWM_CHAN   1   /* B */
#define HUB_HM2_FUNC       IO_BANK0_GPIO33_CTRL_FUNCSEL_VALUE_PWM_B_8
#define HUB_PWM2_PIN       PIN_PWM2
#define HUB_PWM2_PWM_SLICE 9
#define HUB_PWM2_PWM_CHAN  0   /* A */
#define HUB_PWM2_FUNC      IO_BANK0_GPIO34_CTRL_FUNCSEL_VALUE_PWM_A_9
_Static_assert(HUB_HM2_PIN == 33 && HUB_PWM2_PIN == 34, "the function names above are for these GPIOs");

/* SWD master of the other seven chips: software SWD from SIO (docs/13 "PIO の割り当て"). At start SWCLK low,
 * SWDIO pulled up (docs/13 "起動・書き込み・リセット", 決まり). When writing RP-AP CTRL, keep bits 1:0 at 0. */
#define HUB_SWD_U1_SWCLK PIN_SWCLK1
#define HUB_SWD_U1_SWDIO PIN_SWDIO1
#define HUB_SWD_U2_SWCLK PIN_SWCLK2
#define HUB_SWD_U2_SWDIO PIN_SWDIO2
#define HUB_SWD_U3_SWCLK PIN_SWCLK3
#define HUB_SWD_U3_SWDIO PIN_SWDIO3
#define HUB_SWD_U4_SWCLK PIN_SWCLK4
#define HUB_SWD_U4_SWDIO PIN_SWDIO4
#define HUB_SWD_U5_SWCLK PIN_SWCLK5
#define HUB_SWD_U5_SWDIO PIN_SWDIO5
#define HUB_SWD_U8_SWCLK PIN_SWCLK8
#define HUB_SWD_U8_SWDIO PIN_SWDIO8
#define HUB_SWD_U9_SWCLK PIN_SWCLK9
#define HUB_SWD_U9_SWDIO PIN_SWDIO9
#define HUB_SWD_COUNT 7
#define HUB_SWD_TARGETS     { 1, 2, 3, 4, 5, 8, 9 }
#define HUB_SWD_SWCLK_PINS  { PIN_SWCLK1, PIN_SWCLK2, PIN_SWCLK3, PIN_SWCLK4, PIN_SWCLK5, PIN_SWCLK8, PIN_SWCLK9 }
#define HUB_SWD_SWDIO_PINS  { PIN_SWDIO1, PIN_SWDIO2, PIN_SWDIO3, PIN_SWDIO4, PIN_SWDIO5, PIN_SWDIO8, PIN_SWDIO9 }
/* the same pins as GPIO masks, for compile-time checks against REVH_CONSOLE_MASK */
#define HUB_SWD_SWCLK_MASK ((1ull << PIN_SWCLK1) | (1ull << PIN_SWCLK2) | (1ull << PIN_SWCLK3) | \
                            (1ull << PIN_SWCLK4) | (1ull << PIN_SWCLK5) | (1ull << PIN_SWCLK8) | \
                            (1ull << PIN_SWCLK9))
#define HUB_SWD_SWDIO_MASK ((1ull << PIN_SWDIO1) | (1ull << PIN_SWDIO2) | (1ull << PIN_SWDIO3) | \
                            (1ull << PIN_SWDIO4) | (1ull << PIN_SWDIO5) | (1ull << PIN_SWDIO8) | \
                            (1ull << PIN_SWDIO9))

/* Reset and core voltage: nRST pulls RUN of U1-U5, U8, U9 low (open drain; 10k pull-up on the board). VSEL
 * (net VSEL_S) turns Q7 on and raises +1V1 to about 1.122 V; 100k pull-down on the board. */
#define HUB_NRST_PIN       PIN_NRST
#define HUB_VSEL_PIN       PIN_VSEL_S

/* U7: second W25Q128JVSIQ on QMI chip select 1 (2.2k pull-up keeps it deselected during boot). The boot ROM
 * treats CS1 as absent until the firmware sets FLASH_DEVINFO; the read format of window 1 is QMI m[1]. */
#define HUB_XIP_CS1_PIN    PIN_QSPI6_SS1
#define HUB_XIP_CS1_FUNC   IO_BANK0_GPIO47_CTRL_FUNCSEL_VALUE_XIP_SS_N_1
_Static_assert(HUB_XIP_CS1_PIN == 47, "the function name above is for GPIO47");

/* Links (receive / send as seen from the hub) and the rest */
#define HUB_LINK_PIN       PIN_LINK_F           /* LINK (U1-U6), 250 ohm */
#define HUB_PLINK_PIN      PIN_PLINK_F          /* PLINK to U2 / U5, 500 ohm each */
#define HUB_WLINK_RX_BASE  PIN_WL_BASE          /* WLINK from U1 */
#define HUB_XH1_RX_BASE    PIN_XH1_RX_BASE      /* XLINK-H1 from U1 */
#define HUB_XH1_TX_BASE    PIN_XH1_TX_BASE      /* XLINK-H1 to U1 */
#define HUB_XH2_RX_BASE    PIN_XH2_RX_BASE      /* XLINK-H2 from U2 */
#define HUB_XH2_TX_BASE    PIN_XH2_TX_BASE      /* XLINK-H2 to U2 */
#define HUB_HIRQ_PIN       PIN_HIRQ             /* interrupt request to U3 */
#define HUB_EXT_PIN        PIN_EXT              /* J4, 0-3.3 V only */
#define HUB_LED_PIN        PIN_LED6

#endif /* FAMICART_REVH_PINS_HUB_H */
